head.script:
scwin.trigger3_onclick = function(e) {
    var gridStr = '<w2:gridView xmlns:w2="http://www.inswave.com/websquare" xmlns:ev="http://www.w3.org/2001/xml-events" dataList="dataList1" scrollByColumn="false" scrollByColumnAdaptive="false" id="gridView1"' +
        '    		style="position: relative;width: 500px;height: 150px;" ignoreCellClick="false" ignoreToggleOnDisabled="false"' +
        '    		fixedColumnWithHidden="true" useShiftKey="true">' +
        '    		<w2:header id="header1" style="">' +
        '    			<w2:row id="row2" style="">' +
        '    				<w2:column blockSelect="false" id="column7" style="height:20px" inputType="text" width="70" displayMode="label"' +
        '    					value="name1">' +
        '    				</w2:column>' +
        '    				<w2:column blockSelect="false" id="column3" style="height:20px" width="70" inputType="text" displayMode="label"' +
        '    					value="name2">' +
        '    				</w2:column>' +
        '    			</w2:row>' +
        '    		</w2:header>' +
        '    		<w2:gBody id="gBody4" style="">' +
        '    			<w2:row id="row5" style="">' +
        '    				<w2:column blockSelect="false" id="col1" style="height:20px" inputType="text" width="70" displayMode="label"></w2:column>' +
        '    				<w2:column blockSelect="false" id="col2" style="height:20px" width="70" inputType="text" displayMode="label"></w2:column>' +
        '    			</w2:row>' +
        '    		</w2:gBody>' +
        '    	</w2:gridView>';
    gridView1.setGridStyle(WebSquare.xml.parse(gridStr, true));
};
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
